package br.com.strumlab.analysis;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import tools.jackson.databind.ObjectMapper;
import br.com.strumlab.songs.*;
import static br.com.strumlab.analysis.AnalysisModels.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest
class AnalysisIT {
    @Autowired AnalysisService analysis;@Autowired SongService songs;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;
    byte[] wav(){byte[] b=new byte[48];System.arraycopy("RIFF".getBytes(StandardCharsets.US_ASCII),0,b,0,4);System.arraycopy("WAVE".getBytes(StandardCharsets.US_ASCII),0,b,8,4);new Random().nextBytes(Arrays.copyOfRange(b,12,48));return b;}
    SongService.Detail song(){var c=new SongContent(1,"Análise autoral "+UUID.randomUUID(),"","G",90,"4/4",2,"manual","Origem preservada","own",List.of(new SongContent.Section("verse","verse","Verso",List.of(new SongContent.Line("line",List.of(new SongContent.Token("chord","G/B",null),new SongContent.Token("text",null,"Texto humano preservado")))))));var s=songs.create(c);return songs.save(s.song().id(),new SongService.Edit(s.draft(),s.baseRevisionId(),s.song().draftVersion()));}
    Detail upload(UUID id){return analysis.upload(id,wav(),"own.wav","audio/wav","own");}
    UUID result(Detail a){UUID job=a.jobs().getFirst().id();var r=new Result(1,AnalysisService.ALGORITHM,10.0,120.0,"C",null,null,List.of(new ChordEvent(0,5,"C"),new ChordEvent(5,10,"G")),List.of("Estimativa não calibrada"));jdbc.update("INSERT INTO analysis_result(id,job_id,result_json) VALUES (?,?,?::jsonb)",UUID.randomUUID(),job,json.writeValueAsString(r));jdbc.update("UPDATE processing_job SET status='completed',attempts=1 WHERE id=?",job);jdbc.update("UPDATE audio_asset SET status='valid',duration_seconds=10 WHERE id=?",a.asset().id());return job;}
    @Test void validatedHeadersRightsQuotaIdempotencyAndPrivateOwnership(){var song=song();var a=upload(song.song().id());var same=upload(song.song().id());assertThat(same.asset().id()).isEqualTo(a.asset().id());assertThat(same.jobs()).hasSize(1);assertThatThrownBy(()->analysis.upload(song.song().id(),new byte[48],"bad.wav","audio/wav","own")).isInstanceOf(SongProblem.class);assertThatThrownBy(()->analysis.upload(song.song().id(),wav(),"own.wav","text/plain","own")).isInstanceOf(SongProblem.class);assertThatThrownBy(()->analysis.upload(song.song().id(),wav(),"own.wav","audio/wav","unspecified")).isInstanceOf(SongProblem.class);assertThatThrownBy(()->analysis.audio(a.asset().id())).isInstanceOf(SongProblem.class);UUID other=UUID.randomUUID();jdbc.update("INSERT INTO workspace(id,name) VALUES (?,?)",other,"Outro dono de testes");jdbc.update("UPDATE song SET owner_id=? WHERE id=?",other,song.song().id());assertThatThrownBy(()->analysis.detail(a.asset().id())).isInstanceOf(SongProblem.class);assertThatThrownBy(()->analysis.job(a.jobs().getFirst().id())).isInstanceOf(SongProblem.class);assertThatThrownBy(()->analysis.delete(a.asset().id())).isInstanceOf(SongProblem.class);}
    @Test void selectiveApprovalPreservesManualTextVersionsCapoAndIdempotency(){var s=song();var a=upload(s.song().id());UUID job=result(a),request=UUID.randomUUID();var choice=new Apply(request,s.song().currentRevisionId(),s.song().draftVersion(),true,125,false,null,false,List.of());var saved=analysis.apply(job,choice);assertThat(saved.draft().bpm()).isEqualTo(125);assertThat(saved.draft().key()).isEqualTo("G");assertThat(saved.draft().sections()).isEqualTo(s.draft().sections());assertThat(saved.draft().capo()).isEqualTo(2);assertThat(saved.revisions().getFirst().source()).isEqualTo("analysis_accepted");assertThat(songs.detail(s.song().id()).revisions().getLast().content()).isEqualTo(s.draft());assertThat(analysis.apply(job,choice).revisions()).hasSize(2);assertThatThrownBy(()->analysis.apply(job,new Apply(UUID.randomUUID(),s.song().currentRevisionId(),s.song().draftVersion(),true,110,false,null,false,List.of()))).isInstanceOf(SongProblem.class).hasMessageContaining("Outra edição");var chords=analysis.apply(job,new Apply(UUID.randomUUID(),saved.song().currentRevisionId(),saved.song().draftVersion(),false,null,true,"C",true,List.of(new ChordEvent(0,5,"C"),new ChordEvent(5,10,"G"))));assertThat(chords.draft().sections()).hasSize(2);assertThat(chords.draft().sections().getFirst()).isEqualTo(s.draft().sections().getFirst());assertThat(analysis.job(job).result().key()).isEqualTo("C");assertThatThrownBy(()->jdbc.update("UPDATE analysis_result SET result_json='{}'::jsonb WHERE job_id=?",job)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
    @Test void retryReprocessingDeletionAndHistoricalResults(){var s=song();var a=upload(s.song().id());UUID id=a.asset().id(),job=a.jobs().getFirst().id();jdbc.update("UPDATE processing_job SET status='failed',attempts=1,error_code='invalid_audio' WHERE id=?",job);var retry=analysis.reprocess(id,new Reprocess(job,false));assertThat(retry.jobs()).hasSize(1);assertThat(retry.jobs().getFirst().id()).isEqualTo(job);result(a);var reprocessed=analysis.reprocess(id,new Reprocess(job,true));assertThat(reprocessed.jobs()).hasSize(2);assertThat(songs.detail(s.song().id()).revisions()).hasSize(1);assertThatThrownBy(()->analysis.reprocess(id,new Reprocess(job,true))).isInstanceOf(SongProblem.class);analysis.delete(id);assertThat(analysis.detail(id).asset().status()).isEqualTo("deleted");assertThat(jdbc.queryForObject("SELECT audio_bytes IS NULL FROM audio_asset WHERE id=?",Boolean.class,id)).isTrue();assertThat(analysis.job(job).result()).isNotNull();assertThat(analysis.detail(id).jobs().getFirst().status()).isEqualTo("cancelled");assertThatThrownBy(()->analysis.audio(id)).isInstanceOf(SongProblem.class);}
    @Test void eventValidationRejectsOverlapNanUnknownAndOutOfDuration(){for(var events:List.of(List.of(new ChordEvent(0,11,"G")),List.of(new ChordEvent(0,2,"G"),new ChordEvent(1,3,"C")),List.of(new ChordEvent(Double.NaN,1,"G")),List.of(new ChordEvent(0,1,"N"))))assertThatThrownBy(()->AnalysisService.validateEvents(events,10)).isInstanceOf(SongProblem.class);}
    @Test void concurrentSameUploadCreatesOneAssetAndJob()throws Exception{var s=song();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);Callable<Detail> op=()->{barrier.await();return upload(s.song().id());};var a=pool.submit(op);var b=pool.submit(op);assertThat(a.get().asset().id()).isEqualTo(b.get().asset().id());assertThat(analysis.list(s.song().id())).hasSize(1);}}
}
